"""Record manually read atlas boundary centre-lines; source scans remain local.

Full-map coordinates use 1872 x 1312; the Nanzhao plate uses 1312 x 1868.
Coastal envelopes are clipped against Natural Earth, never used as coastlines.
"""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
ATLAS = Path('D:/历史地图/中国历史地图集')
controls = [[894,303,100,50],[1080,299,110,50],[1269,264,120,50],
            [886,602,100,40],[1107,598,110,40],[1336,557,120,40],
            [877,902,100,30],[1132,899,110,30],[1391,852,120,30],
            [868,1202,100,20],[1155,1199,110,20],[1444,1145,120,20]]
maps = []

def add(year, file, edges, regions, grid=None, size=None):
    source = ATLAS / file
    maps.append(dict(year=year, fileLabel=source.name, sourceSha256=hashlib.sha256(source.read_bytes()).hexdigest(),
                     redistributable=False, pageSize=size or [1872,1312], gridControls=grid or controls,
                     edges=edges, regions=[dict(id=id, edges=names, label=label) for id,names,label in regions]))

